import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Auth = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const isFormValid = email.trim() !== '' && password.trim() !== '';

  const handleGetCode = (e) => {
    e.preventDefault();
    if (!isFormValid) return;
    // TODO: запрос к backend за кодом подтверждения
    // TODO: navigate('/code')
  };

  return (
    // h-[100dvh] — ровно высота вьюпорта, без скролла
    <div className="relative h-[100dvh] w-full overflow-hidden bg-secondary px-5">

      {/* Декоративный градиентный блик */}
      <div
        aria-hidden
        className="pointer-events-none absolute left-1/2 top-4 h-[170px] w-[260px] -translate-x-1/2 rotate-[-20deg] sm:h-[200px] sm:w-[320px]"
        style={{
          background:
            'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
        }}
      />

      {/* Контент поверх градиента */}
      <div className="relative z-10 mx-auto flex h-full w-full max-w-[480px] flex-col py-6">

        {/* Шапка: заголовок + подзаголовок */}
        <header className="pt-20 sm:pt-28">
          <h1 className="text-[36px] leading-[105%] font-semibold text-black laptop:text-[64px] desktop:text-[32px]">
            Вход
          </h1>
          <p className="mt-2 text-[14px] leading-[120%] text-gray laptop:text-[20px] desktop:text-[14px] desktop:font-medium">
            Введите данные аккаунта, чтобы получить код для входа
          </p>
        </header>

        {/* Форма */}
        <form onSubmit={handleGetCode} noValidate className="mt-8 flex flex-col gap-5">
          {/* Email */}
          <input
            type="email"
            placeholder="email.vsk@gmail.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="h-12 w-full bg-transparent text-[16px] text-black placeholder-gray
                       focus:outline-none laptop:text-[20px] desktop:text-[14px]"
          />

          {/* Пароль */}
          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="Пароль"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="h-12 w-full bg-transparent pr-12 text-[16px] text-black placeholder-gray
                         focus:outline-none laptop:text-[20px] desktop:text-[14px]"
            />
            <button
              type="button"
              aria-label={showPassword ? 'Скрыть пароль' : 'Показать пароль'}
              onClick={() => setShowPassword((v) => !v)}
              className="absolute right-0 top-1/2 -translate-y-1/2 p-2 text-gray"
            >
              {showPassword ? (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z" />
                  <circle cx="12" cy="12" r="3" />
                </svg>
              ) : (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z" />
                  <circle cx="12" cy="12" r="3" />
                  <path d="M4 4l16 16" />
                </svg>
              )}
            </button>
          </div>

          {/* Забыли пароль? */}
          <div className="flex justify-end">
            <button
              type="button"
              className="text-[14px] leading-[120%] text-gray"
              onClick={() => { /* TODO */ }}
            >
              Забыли пароль?
            </button>
          </div>

          {/* Кнопка */}
          <button
            type="submit"
            disabled={!isFormValid}
            className={`h-12 w-full rounded-full text-[16px] font-medium transition-colors
              ${isFormValid
                ? 'bg-accent text-black'
                : 'cursor-not-allowed bg-gray/50 text-primary'}`}
          >
            Получить код
          </button>
        </form>

        {/* Условия */}
        <p className="mt-8 text-center text-[12px] leading-[120%] text-gray">
          Продолжая, я принимаю условия
          <br />
          <button
            type="button"
            className="mt-1 text-[14px] font-medium text-black"
            onClick={() => { /* TODO */ }}
          >
            Политики конфиденциальности
          </button>
        </p>

        {/* Футер — mt-auto прижимает его к самому низу */}
        <p className="mt-auto pb-2 pt-4 text-center text-[14px] leading-[120%] text-gray">
          Нет аккаунта?{' '}
          <button
            type="button"
            className="text-black"
            onClick={() => navigate('/register')}
          >
            Зарегистрироваться
          </button>
        </p>
      </div>
    </div>
  );
};

export default Auth;
